or.script1:
function check() {
	var action = workflowData.getMetaDataMap().get("actionTakenByPreparer");
	log.info("action by preparer:" + action);	
    if ((action == "Cancel Request")) {        
        return true;
    }
    else {
        return false;
    }
}

or.script2:
function check() {
	var action = workflowData.getMetaDataMap().get("actionTakenByPreparer");
	log.info("action by preparer:" + action);	
    if ((action != "Cancel Request")) {        
        return true;
    }
    else {
        return false;
    }
}

